@extends('layouts.app') @section('title','Periods') @section('content')<h1>Accounting Periods</h1><table><thead><tr><th>Period</th><th>Dates</th><th>Status</th><th>Actions</th></tr></thead><tbody>@foreach($periods as $p)<tr><td>{{ $p->name }}</td><td>{{ $p->start_date->format('Y-m-d') }} — {{ $p->end_date->format('Y-m-d') }}</td><td>{{ $p->status }}</td><td class="actions">@if($p->status==='open'&&auth()->user()->hasPermission('periods.close'))<form method="post" action="{{ route('periods.close',$p) }}">@csrf<button>Close</button></form>@elseif($p->status==='closed'&&auth()->user()->hasPermission('periods.reopen'))<form method="post" action="{{ route('periods.reopen',$p) }}">@csrf<input name="reason" placeholder="Reopen reason" required><button>Reopen</button></form>@endif</td></tr>@endforeach</tbody></table><h2>Fiscal Years</h2><table><tr><th>Year</th><th>Status</th><th>Actions</th></tr>@foreach($years as $y)<tr><td>{{ $y->year }}</td><td>{{ $y->status }}</td><td>@if($y->status==='open'&&auth()->user()->hasPermission('fiscal_year.close'))<form method="post" action="{{ route('years.close',$y) }}">@csrf<input name="reason" value="Year-end close"><button>Close year</button></form>@elseif($y->status==='closed'&&auth()->user()->hasPermission('fiscal_year.reopen'))<form method="post" action="{{ route('years.reopen',$y) }}">@csrf<input type="date" name="date" required><input name="reason" required placeholder="Reason"><button>Reopen year</button></form>@endif</td></tr>@endforeach</table>@endsection
